const crypto = require('crypto');
const headers = $json.headers ?? {};
const tokenHeader = String(headers['x-govhub-token'] || headers['X-GOVHUB-TOKEN'] || '').trim();
const contentType = String(headers['content-type'] || headers['Content-Type'] || '').toLowerCase();
const allowed = String($env.GOVHUB_TOKENS || '').split(',').map(v => v.trim()).filter(Boolean);
if (!tokenHeader || !allowed.includes(tokenHeader)) {
  return [{ json: { route: 'error', statusCode: 401, status: 'unauthorized', error_code: 'AUTH_INVALID_TOKEN', message: 'invalid token' } }];
}
let tokenScopes = [];
let rawScopes = '';
try {
  rawScopes = String($env.GOVHUB_TOKEN_SCOPES_JSON || '').trim();
  if (rawScopes) {
    const parsed = JSON.parse(rawScopes);
    if (Array.isArray(parsed[tokenHeader])) tokenScopes = parsed[tokenHeader].map((s) => String(s).trim());
  }
} catch {}
if (tokenScopes.length === 0 && rawScopes === '') {
  tokenScopes = ['s:w'];
}
if (!(tokenScopes.includes('s:w') || tokenScopes.includes('snapshots:write'))) {
  return [{ json: { route: 'error', statusCode: 403, status: 'forbidden', error_code: 'AUTH_SCOPE_REQUIRED', message: 'token missing required write scope (s:w)' } }];
}
if (!contentType.includes('application/json')) {
  return [{ json: { route: 'error', statusCode: 400, status: 'invalid_request', error_code: 'CONTENT_TYPE_REQUIRED', message: 'Content-Type must be application/json' } }];
}
let body = $json.body ?? {};
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch { body = {}; }
}
const required = ['run_id','mission_id','branch','status','phase','nn','total','udn_state'];
for (const k of required) {
  if (body[k] === undefined || body[k] === null || String(body[k]).trim() === '') {
    return [{ json: { route: 'error', statusCode: 400, status: 'invalid_request', error_code: 'SNAPSHOT_UPDATE_INVALID_PAYLOAD', message: 'missing field: ' + k } }];
  }
}
const canonicalUdn = String(body.udn_state)
  .replace(/\r\n/g, '\n')
  .split('\n')
  .map((l) => l.trim())
  .filter((l) => l.length > 0)
  .join('\n');
if (!canonicalUdn) {
  return [{ json: { route: 'error', statusCode: 400, status: 'invalid_request', error_code: 'UDN_STATE_INVALID', message: 'udn_state must not be empty after canonicalization' } }];
}
const computedHash = crypto.createHash('sha256').update(Buffer.from(canonicalUdn, 'utf8')).digest('hex');
if (body.integrity_hash && String(body.integrity_hash).trim() !== computedHash) {
  return [{ json: { route: 'error', statusCode: 400, status: 'invalid_request', error_code: 'INTEGRITY_HASH_MISMATCH', message: 'client integrity_hash mismatch' } }];
}
const esc = (v) => String(v ?? '').replace(/'/g, "''");
const nn = Number(body.nn);
const total = Number(body.total);
if (!Number.isFinite(nn) || !Number.isFinite(total)) {
  return [{ json: { route: 'error', statusCode: 400, status: 'invalid_request', error_code: 'SNAPSHOT_UPDATE_INVALID_NUMBERS', message: 'nn and total must be numeric' } }];
}
const excerpt = body.last_error_excerpt_256 ? String(body.last_error_excerpt_256).slice(0, 256) : '';
return [{ json: {
  route: 'valid',
  run_id: String(body.run_id),
  mission_id: String(body.mission_id),
  branch: String(body.branch),
  status: String(body.status),
  phase: String(body.phase),
  nn: Math.trunc(nn),
  total: Math.trunc(total),
  last_event_ts: body.last_event_ts ? String(body.last_event_ts) : '',
  last_error_code: body.last_error_code ? String(body.last_error_code) : '',
  last_error_excerpt_256: excerpt,
  report_ref: body.report_ref ? String(body.report_ref) : '',
  udn_state_canonical: canonicalUdn,
  integrity_hash: computedHash,
  run_id_sql: esc(body.run_id),
  mission_id_sql: esc(body.mission_id),
  branch_sql: esc(body.branch),
  status_sql: esc(body.status),
  phase_sql: esc(body.phase),
  last_event_ts_sql: esc(body.last_event_ts ?? ''),
  last_error_code_sql: esc(body.last_error_code ?? ''),
  last_error_excerpt_256_sql: esc(excerpt),
  report_ref_sql: esc(body.report_ref ?? ''),
  udn_state_canonical_sql: esc(canonicalUdn),
  integrity_hash_sql: esc(computedHash)
} }];

const zlib = require('zlib');
const crypto = require('crypto');
const raw = $json.mission_runs ?? [];
const runs = Array.isArray(raw) ? raw : (typeof raw === 'string' ? JSON.parse(raw) : []);
const payloadObj = {
  ccp_ver: '1.0',
  type: 'mission_runs_v1',
  generated_at_utc: new Date().toISOString(),
  total_runs: runs.length,
  runs
};
const payloadJson = JSON.stringify(payloadObj);
const zipped = zlib.gzipSync(Buffer.from(payloadJson, 'utf8'));
const payload_b64 = zipped.toString('base64');
const payload_sha256 = crypto.createHash('sha256').update(zipped).digest('hex');
const payload_size_bytes = zipped.length;
const esc = (v) => String(v ?? '').replace(/'/g, "''");
return [{ json: {
  snapshot_type: 'mission_runs_v1',
  protocol: 'UBIN',
  version: '1.0',
  encoding: 'json',
  compression: 'gzip',
  payload_b64,
  payload_sha256,
  payload_size_bytes,
  created_by: 'snapshot-update',
  source_repo: 'platform',
  source_ref: '',
  snapshot_type_sql: 'mission_runs_v1',
  protocol_sql: 'UBIN',
  version_sql: '1.0',
  encoding_sql: 'json',
  compression_sql: 'gzip',
  payload_b64_sql: esc(payload_b64),
  payload_sha256_sql: payload_sha256,
  created_by_sql: 'snapshot-update',
  source_repo_sql: 'platform',
  source_ref_sql: ''
} }];
